/**
 * @method
 * @name scwin.grd_pageList_fmt_status
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData r c
 * @returns
 * @hidden N
*/
scwin.grd_pageList_fmt_status = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_pageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "trnsmYn") ?? '') : '');
        if (v === 'Y') { return String((dl && dl.getCellData ? dl.getCellData(r, "status") : '') ?? ''); }
        if (v === 'N') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + (console.error('[sdd] 미실현 라벨 갈래: status (image)'), String(data ?? '')) + '</a>'; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_pageList.status" }); return String(data ?? ''); }
};

