*/
scwin.prelistEnt = async function (bzProcsNo, billLstSaveStatCd) {
    /* sdd-asis-lifecycle:begin fn_PrelistEnt — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_PrelistEntReq').set('bzProcsNo', bzProcsNo);
    $c.util.getComponent('dma_PrelistEntReq').set('billLstSaveStatCd', billLstSaveStatCd);
    scwin.form.action = '/list/prelist.do';
    $c.util.getComponent('dma_PrelistEntReq').set('method', 'prelistSearch');
    await scwin.tx_fn_PrelistEnt();
    /* sdd-asis-lifecycle:end */
};


