    $c.util.getComponent('dma_PrelistEntReq').set('prelmInvstgComTpCd', sVal);
    $c.util.getComponent('dma_PrelistEntReq').set('billLstSaveStatCd', "0");
    $c.util.getComponent('dma_PrelistEntReq').set('trnsmYn', "N");
    scwin.form.action = '/list/prelist.do';
    $c.util.getComponent('dma_PrelistEntReq').set('method', 'prelistSearch');
    await scwin.tx_fn_New();
    /* sdd-asis-lifecycle:end */
};


