/**
 * @method
 * @name scwin.prelistSub
 * @author Inswave
 * @date 2026. 09. 29
 * @param bzProcsNo billLstSaveStatCd
 * @returns
 * @hidden N
*/
scwin.prelistSub = async function (bzProcsNo, billLstSaveStatCd) {
    /* sdd-asis-lifecycle:begin fn_PrelistSub — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ((billLstSaveStatCd) < 9) {
        await $c.win.alert("회사채발행 또는 보호예수 페이지까지 입력을 하셔야만 제출 하실수 있습니다.\n\n해당사항이 없는 경우는 \n\n각  페이지에서 해당사항없음을 클릭해주세요.");
        return;
    }
    $c.util.getComponent('dma_PrelistEntReq').set('bzProcsNo', bzProcsNo);
    $c.util.getComponent('dma_PrelistEntReq').set('trnsmYn', "Y");
    scwin.form.action = '/list/prelistPage.do';
    $c.util.getComponent('dma_PrelistEntReq').set('method', 'prelistPageSub');
    await scwin.tx_fn_PrelistSub();
    /* sdd-asis-lifecycle:end */
};


